x_comment(x_completeExtentDecidableForValueInArg,"(#$completeExtentDecidableForValueInArg PRED VALUE ARGNUM) means that when the            #$CycInferenceEngine                                                                                 is asked a closed query of the form (PRED ... VALUE ...) where VALUE appears in the                  ARGNUMth position, either it can prove (PRED ... VALUE ...) without transformation,                  or (#$not (PRED ... VALUE ...)) is true.") :- x_cid(a65b12712a3910).
